INSERT INTO `effects` (`id`, `subCategoryId`, `combatcount`, `description`, `dice`, `duration`, `name`, `timeduration`, `lapcount`, `durationtype`) VALUES
                                                                                                                                                        (1,	1,	NULL,	'Signe distinctif sans importance.',	2,	NULL,	'Doigt en plus',	NULL,	NULL,	'forever'),
                                                                                                                                                        (2,	1,	NULL,	'Permet de respirer sous l\'eau',	3,	NULL,	'Branchies',	NULL,	NULL,	'forever'),
                                                                                                                                                        (3,	1,	NULL,	'Signe distinctif difficile à cacher.',	4,	NULL,	'Bosse',	NULL,	NULL,	'forever'),
                                                                                                                                                        (5,	1,	NULL,	'Signe distinctif difficile à cacher, handicapant.',	5,	NULL,	'Allongement des bras',	NULL,	NULL,	'forever'),
                                                                                                                                                        (6,	1,	NULL,	'Signe distinctif facile à cacher (bandeau, casque). Donne la vision nocturne.',	6,	NULL,	'Troisième oeil sur le front',	NULL,	NULL,	'forever'),
                                                                                                                                                        (7,	1,	NULL,	'Signe distinctif difficile à cacher, ouïe décuplée.',	7,	NULL,	'Oreilles géantes',	NULL,	NULL,	'forever'),
                                                                                                                                                        (8,	1,	NULL,	'Signe distinctif difficile à cacher, ne peut porter de casque. Coup de boule dangereux !',	8,	NULL,	'Cornes',	NULL,	NULL,	'forever'),
                                                                                                                                                        (9,	1,	NULL,	'Signe distinctif sans importance. Morsure douloureuse, peut trancher la chair.',	9,	NULL,	'Dents aiguisées',	NULL,	NULL,	'forever'),
                                                                                                                                                        (10,	1,	NULL,	'Canalise l\'énergie. Double la récupération des PA de tous les mages/prêtres du groupe.',	10,	NULL,	'Canalisateur',	NULL,	NULL,	'forever'),
                                                                                                                                                        (11,	1,	NULL,	'Nage très vite et efficacement. Ne peut porter de chaussures ou bottes, et c\'est plutôt moche.',	11,	NULL,	'Gros pieds palmés',	NULL,	NULL,	'forever'),
                                                                                                                                                        (12,	1,	NULL,	'Signe distinctif difficile à cacher. Bonus combat à mains nues : 1D+2',	12,	NULL,	'Griffes',	NULL,	NULL,	'forever'),
                                                                                                                                                        (13,	2,	NULL,	'Le personnage ressemble à un ange et devient très impressionnant. Il peut voler, mais ne peut utiliser de sac à dos. Difficultés dans les endroits confinés.',	1,	NULL,	'Ailes emplumées',	NULL,	NULL,	'forever'),
                                                                                                                                                        (14,	2,	NULL,	'Permet d\'ajouter 1 arme et 1 attaque/assaut, ou une parade (au choix). Assez moche. Les vêtements doivent être adaptés. Au choix du destin, droite ou gauche.',	2,	NULL,	'Bras en plus',	NULL,	NULL,	'forever'),
                                                                                                                                                        (15,	2,	NULL,	'Augmentation de la taille et de la force. Le héros doit changer ses vêtements et armures.',	3,	NULL,	'Colosse',	NULL,	NULL,	'forever'),
                                                                                                                                                        (16,	2,	NULL,	'Le personnage a l\'air démoniaque et animal, mais contrebalance par son air impressionnant. Il peut voler, mais ne peut utiliser de sac à dos. Difficultés dans les endroits confinés.',	4,	NULL,	'Ailes squameuses',	NULL,	NULL,	'forever'),
                                                                                                                                                        (17,	2,	NULL,	'La peau écailleuse rend le héros particulièrement laid. En revanche elle est dure à percer !',	5,	NULL,	'Peau écailleuse',	NULL,	NULL,	'forever'),
                                                                                                                                                        (18,	2,	NULL,	'Empêche le personnage de porter un sac à dos. Permet d\'ajouter 1 arme et 1 attaque/assaut.',	6,	NULL,	'Tentacule dorsal',	NULL,	NULL,	'forever'),
                                                                                                                                                        (19,	2,	NULL,	'Un bras en plus de chaque côté, ce n\'est pas forcément très pratique, on s\'emmêle un peu. Cependant, ils donnent 1 attaque et et 1 parade en plus à chaque assaut.',	7,	NULL,	'Deux bras en plus',	NULL,	NULL,	'forever'),
                                                                                                                                                        (20,	2,	NULL,	'Le personnage peut grimper aux murs et peut escalader n\'importe quoi sans épreuve. Peut même se cacher au plafond. Il éprouve des difficultés à garder sa petite amie.',	8,	NULL,	'Spider touch',	NULL,	NULL,	'forever'),
                                                                                                                                                        (21,	2,	NULL,	'Le personnage se sent bizarre, et deviendra un homme-loup à la nuit tombée. Il sera alors totalement incontrôlable et voudra dévorer ses camarades.',	9,	NULL,	'Lycanthropie',	NULL,	NULL,	'forever'),
                                                                                                                                                        (22,	2,	NULL,	'Le personnage se couvre d\'une fourrure épaisse. Il ne craint plus le froid mais il sent mauvais. Il gagne en force et possède l\'odorat d\'un orque (flaire le danger à 50m).',	10,	NULL,	'C\'est velu',	NULL,	NULL,	'forever'),
                                                                                                                                                        (23,	2,	NULL,	'Le héros peut maintenant lire les pensées de quelqu\'un sur épreuve INT (sauf rés. Magie).',	11,	NULL,	'Télépathe',	NULL,	NULL,	'forever'),
                                                                                                                                                        (24,	2,	NULL,	'Les os du héros deviennent si durs qu\'il ne peut plus subir la moindre fracture.',	12,	NULL,	'Solidité',	NULL,	NULL,	'forever'),
                                                                                                                                                        (25,	2,	NULL,	'Le feu ne peut plus altérer la santé du héros, en revanche ça ne protège pas son équipement.',	13,	NULL,	'Ignifugé',	NULL,	NULL,	'forever'),
                                                                                                                                                        (26,	2,	NULL,	'La boîte crânienne du héros grossit en même temps que son cerveau, ses muscles s\'atrophient.',	14,	NULL,	'Petit génie',	NULL,	NULL,	'forever'),
                                                                                                                                                        (27,	2,	NULL,	'Le personnage ne peut porter de sac à dos et il est également bossu. Ne peut voler.',	15,	NULL,	'Ailes embryonnaires',	NULL,	NULL,	'forever'),
                                                                                                                                                        (28,	2,	NULL,	'Diminution de la taille et de la force. Le héros doit changer ses vêtements et armures.',	16,	NULL,	'Minus',	NULL,	NULL,	'forever'),
                                                                                                                                                        (29,	2,	NULL,	'Le personnage a trois jambes. Hélas, ça ne sert pas à grand-chose et ce n\'est pas pratique. Il se déplace moins vite. Les vêtements doivent être adaptés également.',	17,	NULL,	'Jambe en plus',	NULL,	NULL,	'forever'),
                                                                                                                                                        (30,	2,	NULL,	'Le personnage se couvre de flammes de façon aléatoire. Il brûle tout ce qu\'il touche, y compris son équipement. Il peut infliger des dégâts par simple contact : 2D+2. Il ne peut s\'habiller que de vêtements de mailles métalliques.',	18,	NULL,	'Corps enflammé',	NULL,	NULL,	'forever'),
                                                                                                                                                        (31,	2,	NULL,	'Le personnage perd sa consistance et devient translucide. Il peut traverser n\'importe quelle matière mais ne peut plus transporter d\'équipement ou manipuler d\'objets. Il communique cependant et peut toujours lancer des sorts ou prodiges. Il est immunisé aux coups. Éthéré : dans ce cas précis, AD ne sert plus à rien, FO est à zéro, AT et PRD n\'ont pas lieu d\'être. Résistance magie +5. Vulnérable au feu, à l\'électricité...',	19,	NULL,	'Éthéré',	NULL,	NULL,	'forever'),
                                                                                                                                                        (32,	2,	NULL,	'La tête du personnage est remplacée par un gros tentacule très laid. Le héros ne peut plus voir, entendre, penser, s\'alimenter, et la respiration se fait par un petit orifice. La mutation doit être inversée dans les 48H ou il mourra.',	20,	NULL,	'Têtacule',	NULL,	NULL,	'forever'),
                                                                                                                                                        (33,	3,	NULL,	'Le héros sombre dans une paranoïa profonde, se renferme sur lui-même',	1,	NULL,	'Paranoïa',	NULL,	NULL,	'forever'),
                                                                                                                                                        (34,	3,	NULL,	'Le héros, incapable de se concentrer, est victime de débilité',	2,	NULL,	'Débilité',	NULL,	NULL,	'forever'),
                                                                                                                                                        (35,	3,	NULL,	'Le héros est troublé car il pense avoir changé de sexe, il agit bizarrement',	3,	NULL,	'Pensées troublantes I',	NULL,	NULL,	'forever'),
                                                                                                                                                        (36,	3,	NULL,	'Le héros est soudain obsédé par la nourriture et doit manger toutes les heures - cet état l\'empêche de dormir',	4,	NULL,	'Faim dévorante',	NULL,	NULL,	'forever'),
                                                                                                                                                        (37,	3,	NULL,	'Le héros est soudain obsédé par le sexe et cet état l\'empêche de dormir',	5,	NULL,	'Pensées troublantes II',	NULL,	NULL,	'forever'),
                                                                                                                                                        (38,	3,	NULL,	'Le héros est enragé et pense qu\'il est un barbare, il ne lance plus de sorts et attaque à vue au corps-à- corps – s\'il était déjà barbare, la folie n\'a pas d\'effet',	6,	NULL,	'Barbarisme',	NULL,	NULL,	'forever'),
                                                                                                                                                        (39,	3,	NULL,	'Le héros développe une deuxième personnalité, du sexe opposé et violente, qui peut ressortir en cas de stress (chiffre pair au D6) et cette personnalité ne peut jeter des sorts',	7,	NULL,	'Schyzophrénie',	NULL,	NULL,	'forever'),
                                                                                                                                                        (40,	3,	NULL,	'Le héros devient émotionnellement très fragile, il peut s\'évanouir à la vue du danger s\'il fait 5 ou 6 au D6',	8,	NULL,	'Émotivité',	NULL,	NULL,	'forever'),
                                                                                                                                                        (41,	3,	NULL,	'Le héros ne peut plus parler, quelque chose a craqué en lui – de fait, il ne pourra plus lancer que des sorts silencieux',	9,	NULL,	'Mutisme',	NULL,	NULL,	'forever'),
                                                                                                                                                        (42,	3,	NULL,	'Le héros a très peur du noir : il produira de la lumière en permanence ou se collera à une personne qui produit de la lumière - cet état l\'empêche de dormir',	10,	NULL,	'Peur de l\'obscur',	NULL,	NULL,	'forever'),
                                                                                                                                                        (43,	3,	NULL,	'Le héros a craqué : la bave à la bouche, il tremble en permanence et ne peut plus dormir',	11,	NULL,	'Craquage',	NULL,	NULL,	'forever'),
                                                                                                                                                        (44,	3,	NULL,	'Le héros perd goût à la vie : il devient suicidaire et doit être surveillé à tout moment - en cas de stress il a 50% de chance d\'essayer de se suicider à l\'arme blanche',	12,	NULL,	'Suicidaire',	NULL,	NULL,	'forever'),
                                                                                                                                                        (45,	3,	NULL,	'Le héros devient sadique : la seule chose qui lui importe à présent, c\'est d\'infliger le plus de souffrance possible à ses ennemis - il ne s\'intéressera plus à rien d\'autre et délaissera toute autre préoccupation - cet état l\'empêche de dormir',	13,	NULL,	'Sadisme',	NULL,	NULL,	'forever'),
                                                                                                                                                        (46,	3,	NULL,	'Le héros devient complètement masochiste : il rêve de se voir infliger les souffrances les plus cuisantes et se mettra volontairement en danger - cela l\'empêche de dormir',	14,	NULL,	'Masochisme',	NULL,	NULL,	'forever'),
                                                                                                                                                        (47,	3,	NULL,	'Le héros devient exhibitionniste et complètement réfractaire aux vêtements : il devra se promener nu ou entrera dans une rage folle (héros nu : INT-2 pour TOUT LE GROUPE)',	15,	NULL,	'Exhibitionnisme',	NULL,	NULL,	'forever'),
                                                                                                                                                        (48,	3,	NULL,	'Le héros devient narcoleptique : en cas de stress il pourra s\'endormir sur place s\'il fait 5 ou 6 au D6 - il ne peut pas rester 5 minutes inactif sans s\'endormir',	16,	NULL,	'Narcolepsie',	NULL,	NULL,	'forever'),
                                                                                                                                                        (49,	3,	NULL,	'Le héros a une vision : devenu fou, il pense qu\'il est l\'élu de Braav\' et agira en fonction des préceptes de ce dieu',	17,	NULL,	'Révélation',	NULL,	NULL,	'forever'),
                                                                                                                                                        (50,	3,	NULL,	'Le héros est devenu un violent cleptomane : toutes les 15 minutes il tentera de s\'emparer des biens de quelqu\'un proche de lui, par la ruse ou par la force - cela l\'empêche de dormir',	18,	NULL,	'Cleptomanie',	NULL,	NULL,	'forever'),
                                                                                                                                                        (51,	3,	NULL,	'Le héros pense qu\'il est allergique à la nourriture et que des parasites vivent à l\'intérieur de lui : il refuse de s\'alimenter ou de boire des potions, et cet état l\'empêche de dormir',	19,	NULL,	'Grève de la faim',	NULL,	NULL,	'forever'),
                                                                                                                                                        (52,	3,	NULL,	'Devenu momentanément hémiplégique, le héros ne peut plus utiliser que son bras gauche et se déplace difficilement',	20,	NULL,	'Hémiplégie',	NULL,	NULL,	'forever'),
                                                                                                                                                        (53,	4,	NULL,	NULL,	NULL,	NULL,	'1 oeil crevé',	NULL,	NULL,	'forever'),
                                                                                                                                                        (54,	4,	NULL,	NULL,	NULL,	NULL,	'Tous les yeux crevés',	NULL,	NULL,	'forever'),
                                                                                                                                                        (55,	4,	NULL,	NULL,	NULL,	NULL,	'Genoux luxé',	604800,	NULL,	'time'),
                                                                                                                                                        (56,	4,	NULL,	NULL,	NULL,	NULL,	'Coude droit luxé',	604800,	NULL,	'time'),
