                                                                                                                                                   (17,	'Oeil de crapeau',	'{\"icon\": {\"name\": \"brass-eye\", \"color\": \"#566204\", \"rotation\": 0}, \"price\": 1, \"space\": \"négligeable\", \"diceDrop\": 25, \"throwable\": 0, \"description\": \"Il s\'agit d\'un œil frais, et dont la période de conservation est donc très courte (quelques jours). Vendu en fiole.\", \"quantifiable\": 1, \"availableLocation\": \"magasin pour mage, prélevé sur un crapaud\"}',	'Oeil de crapeau',	NULL,	'official',	NULL,	NULL,	'5c3f3dcf-0b20-11ea-bd72-4c72b9310a53'),
                                                                                                                                                   (17,	'Morceau de bois a usage magique',	'{\"icon\": {\"name\": \"planks\", \"color\": \"#ae6507\", \"rotation\": 0}, \"price\": 1, \"space\": \"100 grammes par morceau\", \"diceDrop\": 26, \"throwable\": 0, \"description\": \"Ces morceaux de bois sont spécialement traités pour les pratiques magiques. Impossible de le faire soi-même.\", \"quantifiable\": 1, \"availableLocation\": \"magasin pour mage\"}',	'Morceau de bois à usage magique',	NULL,	'official',	NULL,	NULL,	'5c3f3e0e-0b20-11ea-bd72-4c72b9310a53'),
