INSERT INTO `job_restrictions` (`id`, `jobId`, `text`, `flags`) VALUES
                                                                    (1,	'42a9c242-0b20-11ea-bd72-4c72b9310a53',	'voir les restrictions d\'origine pour ce qui concerne le matériel magique, les armes et les protections enchantées',	NULL),
                                                                    (2,	'42a9c394-0b20-11ea-bd72-4c72b9310a53',	'n’utilise pas d’armure supérieure à PR3 (sauf magique)',	NULL),
                                                                    (3,	'42a9c43c-0b20-11ea-bd72-4c72b9310a53',	'n’utilise pas d’armure supérieure à PR3 (sauf magique)',	NULL),
                                                                    (4,	'42a9c4c4-0b20-11ea-bd72-4c72b9310a53',	'doit utiliser les armes et protections autorisées par le dieu ou démon affilié',	'[{\"type\": \"USE_RELATED_GOD_STUFF\"}]'),
                                                                    (5,	'42a9c4c4-0b20-11ea-bd72-4c72b9310a53',	'doit se plier aux règles de vie relatives au dieu ou démon affilié',	NULL),
                                                                    (6,	'42a9c54a-0b20-11ea-bd72-4c72b9310a53',	'ne peut utiliser autre chose que : bâton, poignard, dague, gourdin comme arme de combat rapproché',	'[{\"data\": \"EPEE\", \"type\": \"NO_WEAPON_TYPE\"}, {\"data\": \"HACHE\", \"type\": \"NO_WEAPON_TYPE\"}]'),
                                                                    (7,	'42a9c54a-0b20-11ea-bd72-4c72b9310a53',	'n’utilise pas les arcs ou arbalètes',	'[{\"data\": \"ARBALETE\", \"type\": \"NO_WEAPON_TYPE\"}, {\"data\": \"ARC\", \"type\": \"NO_WEAPON_TYPE\"}]'),
                                                                    (8,	'42a9c54a-0b20-11ea-bd72-4c72b9310a53',	'n’utilise pas les boucliers',	'[{\"data\": \"BOUCLIER\", \"type\": \"NO_WEAPON_TYPE\"}]'),
                                                                    (9,	'42a9c54a-0b20-11ea-bd72-4c72b9310a53',	'transport de charge limitée à 10 kilos (ou moins selon race)',	NULL),
                                                                    (10,	'42a9c54a-0b20-11ea-bd72-4c72b9310a53',	'n’utilise pas d’armure supérieure à PR2 (sauf magique)',	NULL),
                                                                    (11,	'42a9c5d0-0b20-11ea-bd72-4c72b9310a53',	'liées au dieu auquel le paladin a voué son âme (voir fiches descriptive pour chaque dieu)',	NULL),
                                                                    (12,	'42a9c5d0-0b20-11ea-bd72-4c72b9310a53',	'doit posséder une relique du dieu en question pour utiliser ses pouvoirs (sinon, il ne sera qu\'un aspirant paladin)',	'[{\"type\": \"REQUIRE_RELIC\"}]'),
                                                                    (13,	'42a9c651-0b20-11ea-bd72-4c72b9310a53',	'n’utilise pas d’armure supérieure à PR4 (sauf magique ou “spécial voleur/ranger”)',	NULL),
                                                                    (14,	'42a9c6d1-0b20-11ea-bd72-4c72b9310a53',	'n’utilise pas d’armure supérieure à PR2 (sauf magique)',	NULL),
                                                                    (15,	'42a9c6d1-0b20-11ea-bd72-4c72b9310a53',	'ne peut utiliser autre chose que : bâton, poignard, dague, gourdin ou instrument comme arme de combat rapproché',	'[{\"data\": \"EPEE\", \"type\": \"NO_WEAPON_TYPE\"}, {\"data\": \"HACHE\", \"type\": \"NO_WEAPON_TYPE\"}, {\"data\": \"MASSE\", \"type\": \"NO_WEAPON_TYPE\"}, {\"data\": \"FENDOIR\", \"type\": \"NO_WEAPON_TYPE\"}, {\"data\": \"LANCE\", \"type\": \"NO_WEAPON_TYPE\"}]'),
                                                                    (16,	'42a9c6d1-0b20-11ea-bd72-4c72b9310a53',	'n\'utilise pas de bouclier',	'[{\"data\": \"BOUCLIER\", \"type\": \"NO_WEAPON_TYPE\"}]'),
                                                                    (17,	'42a9c753-0b20-11ea-bd72-4c72b9310a53',	'n’utilise pas d’armure supérieure à PR3 (sauf magique)',	NULL),
                                                                    (18,	'42a9c753-0b20-11ea-bd72-4c72b9310a53',	'un pirate reste un pirate : il ne peut changer de métier',	'[{\"type\": \"CAN_CHANGE_JOB\"}]'),
                                                                    (19,	'42a9c753-0b20-11ea-bd72-4c72b9310a53',	'ne peut utiliser d\'arme à 2 mains',	'[{\"data\": \"DEUX_MAINS\", \"type\": \"NO_WEAPON_TYPE\"}]'),
                                                                    (20,	'42a9c7cf-0b20-11ea-bd72-4c72b9310a53',	'n’utilise pas d’armure supérieure à PR3 (sauf magique)',	NULL),
                                                                    (21,	'42a9c7cf-0b20-11ea-bd72-4c72b9310a53',	'ne peut utiliser d\'arme à 2 mains',	'[{\"data\": \"DEUX_MAINS\", \"type\": \"NO_WEAPON_TYPE\"}]'),
                                                                    (22,	'42a9c84c-0b20-11ea-bd72-4c72b9310a53',	'n’utilise pas d’armure supérieure à PR3 (sauf magique)',	NULL),
                                                                    (23,	'42a9c84c-0b20-11ea-bd72-4c72b9310a53',	'ne peut utiliser d\'arme à 2 mains',	'[{\"data\": \"DEUX_MAINS\", \"type\": \"NO_WEAPON_TYPE\"}]'),
                                                                    (24,	'42a9c8c9-0b20-11ea-bd72-4c72b9310a53',	'aucune restriction particulière, car le noble pense qu\'il peut tout faire – ce qui est faux bien sûr',	NULL),
                                                                    (25,	'42a9c8c9-0b20-11ea-bd72-4c72b9310a53',	'non, le noble ne peut choisir aucun autre métier que noble, même à haut niveau !',	'[{\"type\": \"NO_OTHER_JOB\"}]'),
                                                                    (32,	'cee56d51-76da-475b-b71a-35cb2da01a9e',	'n’utilise pas d’armure supérieure à PR3 (des restrictions à l\'usage de protections ou de matériel magiques s\'appliqueront en fonction de l\'origine du héros)',	NULL),
                                                                    (33,	'cee56d51-76da-475b-b71a-35cb2da01a9e',	'aucune autre restriction, le traîne-patins ayant tendance à s\'adapter facilement',	NULL),
                                                                    (34,	'cee56d51-76da-475b-b71a-35cb2da01a9e',	'n\'a pas reçu d\'éducation suffisante pour apprendre la compétence « Érudition », et donc ne peut pas lire les parchemins',	'[{\"data\": \"ERUDITION\", \"type\": \"NO_SKILL\"}]');
