INSERT INTO `mastery_groups` (`id`, `name`, `description`, `displayOrder`) VALUES
                                                                         ('9af27c8f-0c53-53db-9dfb-906e9f434b1a',	'Maîtrises d’arme',	'Une « maîtrise d’arme +1 » est un niveau de maîtrise amélioré d’une maîtrise d’arme existante. Elle permet d’avoir un bonus supplémentaire lors du maniement de cette arme.\nPour obtenir une maîtrise d’arme +1, il faut absolument être au niveau 10 minimum, sauf mention contraire, et que votre spécialisation vous donne ou vous permette de prendre une ou plusieurs maîtrises d’arme.\nS’il est fait mention de « gagner » ou « d’obtenir » une maîtrise d’arme +1, vous gagnez ou choisissez la maîtrise en question. S’il est indiqué que vous « débloquez » une maîtrise, vous pouvez prendre votre maîtrise +1 au prix d’un point de maîtrise. Si votre renforcement ou spécialisation ne fait aucune mention de maîtrise +1, il vous est impossible d’en avoir une.\nLes bonus acquis avec les talents et maîtrises d’armes se cumulent, sauf mention contraire.',	1),
                                                                         ('04f50b42-6bde-5303-902a-3a83532418aa',	'Maîtrises d’armure',	'Chaque maîtrise d’armure de base dépend de la PR naturelle de l’armure portée.\nLes points de PR octroyés par les différentes maîtrises ne comptent pas dans le calcul de l’encombrement max. Les points de PR des maîtrises d’armure ne sont pas cumulatifs entre eux, sauf avec la maîtrise des armures +1 qui passe le bonus total à PR+2 (non magique).',	2);
INSERT INTO `masteries` (`id`, `masteryGroupId`, `displayOrder`, `name`, `data`) VALUES
                                                                               ('f8569c1c-0f1e-54b2-803d-14ce6ac528a7',	'9af27c8f-0c53-53db-9dfb-906e9f434b1a',	1,	'Maîtrise de l’arbalète',	'{\"effect\": \"RésoCrit.+2 et réduit de 2 les chances de l’ennemi de bloquer avec un bouclier\"}'),
                                                                               ('bdce8798-94f1-59b8-b6be-e622d90b33c8',	'9af27c8f-0c53-53db-9dfb-906e9f434b1a',	2,	'Maîtrise de l’arbalète +1',	'{\"effect\": \"RésoCrit.+1 et ignore 1 de PR nat.\", \"requiredLevel\": 10, \"prerequisiteMasteryId\": \"f8569c1c-0f1e-54b2-803d-14ce6ac528a7\"}'),
                                                                               ('10324203-95f3-5470-8d03-625f710aa39f',	'9af27c8f-0c53-53db-9dfb-906e9f434b1a',	3,	'Maîtrise de l’arc',	'{\"effect\": \"Réduit de 2 le malus de visée aux tirs localisés\"}'),
                                                                               ('cb68df46-af67-556a-a9a0-1940afe30c1b',	'9af27c8f-0c53-53db-9dfb-906e9f434b1a',	4,	'Maîtrise de l’arc +1',	'{\"effect\": \"RésoCrit.+2\", \"requiredLevel\": 10, \"prerequisiteMasteryId\": \"10324203-95f3-5470-8d03-625f710aa39f\"}'),
                                                                               ('3d2ab807-7adc-51c5-81ea-d809e5cf084c',	'9af27c8f-0c53-53db-9dfb-906e9f434b1a',	5,	'Maîtrise de l’arme d’hast',	'{\"effect\": \"Attaque gratuite sur le premier ennemi pénétrant la zone de contrôle de l’arme (1x/assaut), même après votre esquive\"}'),
                                                                               ('9efccaa8-4d20-580e-95db-a1fe1f456210',	'9af27c8f-0c53-53db-9dfb-906e9f434b1a',	6,	'Maîtrise de l’arme d’hast +1',	'{\"effect\": \"Ignore 1 de PR nat. et provoque un saignement de 1 BL/assaut\", \"requiredLevel\": 10, \"prerequisiteMasteryId\": \"3d2ab807-7adc-51c5-81ea-d809e5cf084c\"}'),
                                                                               ('d17fee2e-2ccc-5e0c-913b-19042446ef48',	'9af27c8f-0c53-53db-9dfb-906e9f434b1a',	7,	'Maîtrise de l’arme à poudre',	'{\"effect\": \"PI+2 avec les armes à poudre\"}'),
                                                                               ('df4d7479-ef63-5b2d-b867-920fd04f5585',	'9af27c8f-0c53-53db-9dfb-906e9f434b1a',	8,	'Maîtrise de l’arme à poudre +1',	'{\"effect\": \"Rechargement des armes à poudre diminué de 2 assauts\", \"requiredLevel\": 10, \"prerequisiteMasteryId\": \"d17fee2e-2ccc-5e0c-913b-19042446ef48\"}'),
                                                                               ('e01b4fa6-d7bb-5f7c-92a4-6a6c0f8a6b60',	'9af27c8f-0c53-53db-9dfb-906e9f434b1a',	9,	'Maîtrise des bâtons et sceptres',	'{\"effect\": \"PRD+2, PI+1\"}'),
                                                                               ('e863863f-d092-536d-805d-f2982232cba7',	'9af27c8f-0c53-53db-9dfb-906e9f434b1a',	10,	'Maîtrise des bâtons et sceptres +1',	'{\"effect\": \"1 attaque supplémentaire à chaque assaut\", \"requiredLevel\": 10, \"prerequisiteMasteryId\": \"e01b4fa6-d7bb-5f7c-92a4-6a6c0f8a6b60\"}'),
                                                                               ('d9406fab-865d-58b1-8332-235986bea5f0',	'9af27c8f-0c53-53db-9dfb-906e9f434b1a',	11,	'Maîtrise des armes bizarres',	'{\"effect\": \"Chance de toucher +2 (AT ou AD) ; PI+1\"}'),
                                                                               ('bd80ade3-950e-5ca0-a0b8-5e326a98da70',	'9af27c8f-0c53-53db-9dfb-906e9f434b1a',	12,	'Maîtrise des armes bizarres +1',	'{\"effect\": \"Chance de toucher +1 (AT ou AD) ; PI+3\", \"requiredLevel\": 10, \"prerequisiteMasteryId\": \"d9406fab-865d-58b1-8332-235986bea5f0\"}'),
                                                                               ('707a30b1-5a44-51c8-b0c0-98c1285d8389',	'9af27c8f-0c53-53db-9dfb-906e9f434b1a',	13,	'Maîtrise du bouclier',	'{\"effect\": \"Résistance : réduit le trait « Puissant » au rang inférieur\"}'),
                                                                               ('e1c645a0-a4c5-5c4f-856b-0a8a08258c6d',	'9af27c8f-0c53-53db-9dfb-906e9f434b1a',	14,	'Maîtrise du bouclier +1',	'{\"effect\": \"Augmente de 1 la réduction de dégâts d’un bouclier. +1 AT par assaut au bouclier (AT-3), le bonus de FO est à ajouter aux dégâts (petit : 1D6 ; moyen : 1D6+2 ; grand : 1D6+4)\", \"requiredLevel\": 10, \"prerequisiteMasteryId\": \"707a30b1-5a44-51c8-b0c0-98c1285d8389\"}'),
                                                                               ('7c0851fd-3c5c-5416-b076-e71c1b963261',	'9af27c8f-0c53-53db-9dfb-906e9f434b1a',	15,	'Maîtrise du lance-pierre/fronde',	'{\"effect\": \"Ignore 2 de PR nat.\"}'),
                                                                               ('6d2d0675-6eb7-5e09-a459-8bc5c4fac593',	'9af27c8f-0c53-53db-9dfb-906e9f434b1a',	16,	'Maîtrise du lance-pierre/fronde +1',	'{\"effect\": \"Ignore 1 de PR nat. et Crit.+1 contre les humanoïdes plus grands que le tireur\", \"requiredLevel\": 10, \"prerequisiteMasteryId\": \"7c0851fd-3c5c-5416-b076-e71c1b963261\"}'),
                                                                               ('00081479-cbb0-50e6-ad66-1b39a0ed1da9',	'9af27c8f-0c53-53db-9dfb-906e9f434b1a',	17,	'Maîtrise haches/haches de jet',	'{\"effect\": \"Lancez deux fois les dégâts et choisissez le résultat\"}'),
                                                                               ('c326b789-8951-54c4-8cc7-95d4fdaf8960',	'9af27c8f-0c53-53db-9dfb-906e9f434b1a',	18,	'Maîtrise haches/haches de jet +1',	'{\"effect\": \"Ignore 1 de PR nat. et Crit.+1\", \"requiredLevel\": 10, \"prerequisiteMasteryId\": \"00081479-cbb0-50e6-ad66-1b39a0ed1da9\"}'),
                                                                               ('8ea49d6f-a81a-56b8-94e3-06267316ea7f',	'9af27c8f-0c53-53db-9dfb-906e9f434b1a',	19,	'Maîtrise des javelots',	'{\"effect\": \"Augmente la portée de 5 m., AD+1 (tir)\"}'),
                                                                               ('6ea0d6e6-7390-5140-a71b-5ac3a6dc775a',	'9af27c8f-0c53-53db-9dfb-906e9f434b1a',	20,	'Maîtrise des javelots +1',	'{\"effect\": \"RésoCrit.+1 et provoque un saignement de 1 BL/assaut\", \"requiredLevel\": 10, \"prerequisiteMasteryId\": \"8ea49d6f-a81a-56b8-94e3-06267316ea7f\"}'),
                                                                               ('3fac2d80-20d2-5f40-b588-fb3de3ad8cf7',	'9af27c8f-0c53-53db-9dfb-906e9f434b1a',	21,	'Maîtrise des lames',	'{\"effect\": \"AT+1 et PRD+1\"}'),
                                                                               ('bbdb3766-f9b5-50a5-b34a-f1b75d9228f1',	'9af27c8f-0c53-53db-9dfb-906e9f434b1a',	22,	'Maîtrise des lames +1',	'{\"effect\": \"Provoque un saignement de 2 BL/assaut\", \"requiredLevel\": 10, \"prerequisiteMasteryId\": \"3fac2d80-20d2-5f40-b588-fb3de3ad8cf7\"}'),
                                                                               ('683a4abb-b76b-5c9f-83e1-a1ef7a7c71c6',	'9af27c8f-0c53-53db-9dfb-906e9f434b1a',	23,	'Maîtrise des dagues, poignards et autres lames courtes',	'{\"effect\": \"RésoCrit.+2\", \"notes\": \"Les armes de pugilat tranchantes comme les katars ou les griffes rentrent dans cette catégorie pour la maîtrise, mais restent considérées comme des armes bizarres ailleurs.\"}'),
                                                                               ('de08e722-d94e-5031-a71b-ae6b97eb525f',	'9af27c8f-0c53-53db-9dfb-906e9f434b1a',	24,	'Maîtrise des dagues, poignards et autres lames courtes +1',	'{\"effect\": \"Crit.+1, RésoCrit.+1\", \"notes\": \"Les armes de pugilat tranchantes comme les katars ou les griffes rentrent dans cette catégorie pour la maîtrise, mais restent considérées comme des armes bizarres ailleurs.\", \"requiredLevel\": 10, \"prerequisiteMasteryId\": \"683a4abb-b76b-5c9f-83e1-a1ef7a7c71c6\"}'),
                                                                               ('7f208165-e7de-54d5-8969-197e1c13d5fa',	'9af27c8f-0c53-53db-9dfb-906e9f434b1a',	25,	'Maîtrise des masses, marteaux et gourdins',	'{\"effect\": \"Ignore 2 de PR nat.\"}'),
                                                                               ('314e3a8f-99bf-5823-bae5-8cc0a0e697a1',	'9af27c8f-0c53-53db-9dfb-906e9f434b1a',	26,	'Maîtrise des masses, marteaux et gourdins +1',	'{\"effect\": \"Ignore 2 de PR nat. et si un ennemi pare une attaque, il subira néanmoins des dégâts directs (BL) à hauteur du bonus de FO\", \"requiredLevel\": 10, \"prerequisiteMasteryId\": \"7f208165-e7de-54d5-8969-197e1c13d5fa\"}'),
                                                                               ('facf2916-3566-51fe-a5fa-dac6f61d5506',	'9af27c8f-0c53-53db-9dfb-906e9f434b1a',	27,	'Maîtrise des armes de récupération',	'{\"effect\": \"PI+1, réduit de 1 le malus à l’AT\"}'),
                                                                               ('ccf44a35-82e3-5e84-8a36-bf5715b18596',	'9af27c8f-0c53-53db-9dfb-906e9f434b1a',	28,	'Maîtrise des armes de bourrins',	'{\"effect\": \"PI+1, réduit les malus liés aux armes à deux mains de 1 (Rappel : cumulable avec les autres maîtrises)\"}'),
                                                                               ('e8a18838-c19d-5fc6-8ca5-42ee0c32156d',	'04f50b42-6bde-5303-902a-3a83532418aa',	1,	'Maîtrise de l’armure légère',	'{\"restriction\": \"PR naturelle max 3\", \"effect\": \"PR+1, +1 aux bonus liés aux armures (ESQ et déplacement)\"}'),
                                                                               ('7f3415ab-0a06-5f78-ac7a-68c01e90837f',	'04f50b42-6bde-5303-902a-3a83532418aa',	2,	'Maîtrise de l’armure intermédiaire',	'{\"restriction\": \"PR naturelle entre 4 et 6\", \"effect\": \"PR+1, réduit les malus liés aux armures de 1 (ESQ et déplacement)\"}'),
                                                                               ('6758085d-1bf3-5c4b-9a23-33ef4f733f1a',	'04f50b42-6bde-5303-902a-3a83532418aa',	3,	'Maîtrise de l’armure lourde',	'{\"restriction\": \"PR naturelle 7 et +\", \"effect\": \"PR+1, réduit de 1 les malus liés aux armures (+1 m/assaut, PR 7 : ESQ-5 | PR 8 et + : ESQ-6)\"}'),
                                                                               ('5b4c8acd-2444-55c9-8031-8d6631487165',	'04f50b42-6bde-5303-902a-3a83532418aa',	4,	'Maîtrise des armures +1',	'{\"restriction\": \"Une maîtrise d’armure de base\", \"effect\": \"PR+1, les dégâts critiques subis n’ignorent plus que la moitié de la PR nat. au lieu de l’ignorer totalement\", \"requiredLevel\": 10}');
