                                                                              (477,	'{"attacks":[{"name":"Impact","at":15,"dmg":"1"}],"prd":null,"esq":0,"ev":140,"ea":null,"pr":4,"pr_magic":null,"cou":15,"chercheNoise":null,"resm":10,"xp":60,"note":"Dégâts : 1 impact (véliers)","sex":null,"page":71,"traits":[]}',	'Requin-Bélier',	49),
                                                                              (478,	'{"attacks":[{"name":"Griffes","at":11,"dmg":"2D+2"}],"prd":null,"esq":13,"ev":40,"ea":null,"pr":2,"pr_magic":null,"cou":20,"chercheNoise":null,"resm":11,"xp":40,"note":"- Invocation de niveau 7\\n- Coût : 20 PA - Rituel : 5 minutes\\n- Appel : MagiePsy-2 - Contrôle : 2D6+11 - Révocation : 3D6+13\\n- Ingrédients : 1 dent de requin, 1 dose de cendres d’un érudit\\n- INT : 7\\n- Peut tenter l’esquive à chaque assaut\\n- Dégâts tranchants/magiques\\n- Invulnérable au feu, à l’air, à l’électricité et à la glace\\n- Stupide et agressif : doit être surveillé à tout moment\\n- Créature invoquée : ne peut pas être soignée","sex":null,"page":null,"traits":[]}',	'Ghukkutuh',	48),
