                                                                              (480,	'{"attacks":[{"name":"Machoire","at":12,"dmg":"1D+4"}],"prd":null,"esq":8,"ev":32,"ea":null,"pr":1,"pr_magic":null,"cou":18,"chercheNoise":null,"resm":20,"xp":32,"note":null,"sex":null,"page":260,"traits":[{"traitId":10,"level":1},{"traitId":1,"level":2},{"traitId":4,"level":2},{"traitId":5,"level":2}]}',	'Sotopaf',	54),
                                                                              (481,	'{"spellBooks":[{"spellBookId":"712829b8-dc3e-532f-b54e-9be4577bc15c","maxLevel":5}],"attacks":[{"at":12,"dmg":"1D+2"}],"prd":11,"esq":null,"ev":18,"ea":28,"pr":2,"pr_magic":null,"cou":10,"chercheNoise":null,"resm":null,"xp":13,"note":"Lance des prodiges des prêtres de Slanoush jusqu\'au niveau 5","sex":null,"page":null,"traits":[]}',	'Mirithl, Prêtresse de Slanoush',	65),
