                                                                           (12,	'3447b1c8-0b20-11ea-bd72-4c72b9310a53',	'Homme',	'/generateurs/noms/fantastiques/fr/masculins/demi-elfes'),
                                                                           (13,	'3447b1c8-0b20-11ea-bd72-4c72b9310a53',	'Femme',	'/generateurs/noms/fantastiques/fr/feminins/demi-elfes'),
