                                                                                             ('fa8ce264-6ecf-5173-b6f9-5b164a933927',	'3bbd2a87-7381-50e8-90fd-b230aed8e825',	4,	'Œil de Robinoude',	'{\"usableBy\": \"Tout héros capable de manier un arc / une arbalète\", \"usage\": \"1 fois par heure\\n- En cas d’échec, attendre 30 min. avant un nouvel essai\", \"effects\": \"dégâts augmentés\", \"test\": \"AD standard\", \"conditions\": \"aucune\", \"damage\": \"dégâts +2, ignore l’armure\", \"criticalFailure\": \"La flèche part de travers et se brise\", \"criticalSuccess\": \"dégâts +4\", \"range\": \"À distance\", \"xp\": 1, \"cooldown\": {\"durationType\": \"time\", \"timeDuration\": 3600}, \"failureCooldown\": {\"durationType\": \"time\", \"timeDuration\": 1800}}'),
