                                                                                             ('52e35daf-f228-5618-a6ff-3703cccd0d83',	'3bbd2a87-7381-50e8-90fd-b230aed8e825',	6,	'Coup bas vraiment bas',	'{\"usableBy\": \"Héros de petite taille, Elfes, noble, ménestrel, marchand\", \"usage\": \"1 fois par heure\\n- En cas d’échec, attendre 30 min. avant un nouvel essai\", \"effects\": \"broyages des parties intimes\\n- COU/AT/PRD -2 pour la cible (4 assauts)\", \"test\": \"AD standard\", \"conditions\": \"après une AT réussie\\n- Fonctionne sur humanoïde, de sexe masculin\", \"damage\": \"-2 PV directs sur la cible\", \"criticalFailure\": \"Le héros trébuche et tombe, rate 3 assauts\", \"criticalSuccess\": \"dégâts 1D6 PV\", \"range\": \"Corps à corps\", \"xp\": 1, \"cooldown\": {\"durationType\": \"time\", \"timeDuration\": 3600}, \"failureCooldown\": {\"durationType\": \"time\", \"timeDuration\": 1800}}'),
